import numpy as np

class PersonalizedFL:
    def __init__(self, global_weights, lam=0.1, alpha=0.5):
        self.global_weights = global_weights
        self.lam = lam
        self.alpha = alpha
    def local_personalized_train(self, global_w, local_data, epochs, lr):
        local_w = {k: v.copy() for k, v in global_w.items()}
        for epoch in range(epochs):
            X, y = local_data
            logits = X @ local_w['W1'] + local_w['b1']
            H = np.maximum(0, logits)
            out = H @ local_w['W2'] + local_w['b2']
            d_out = 2 * (out - y) / len(y)
            dW2 = H.T @ d_out
            db2 = np.sum(d_out, axis=0)
            dH = d_out @ local_w['W2'].T
            d_logits = dH * (H > 0)
            dW1 = X.T @ d_logits
            db1 = np.sum(d_logits, axis=0)
            grads = {'W1': dW1, 'b1': db1, 'W2': dW2, 'b2': db2}
            for k in local_w:
                reg_grad = 2 * self.lam * (local_w[k] - global_w[k])
                local_w[k] -= lr * (grads[k] + reg_grad)
        return local_w
    def interpolate_models(self, global_w, local_w):
        return {k: self.alpha * local_w[k] + (1 - self.alpha) * global_w[k] for k in global_w}
    def personalized_aggregate(self, client_models, client_weights):
        total = sum(client_weights)
        return {k: sum(w * m[k] for w, m in zip(client_weights, client_models)) / total for k in client_models[0]}
